const express = require("express");
const app = express();
app.use(express.json());

function penggunaDari(req) {
  const token = (req.headers.authorization || "").replace("Bearer ", "");
  return PENGGUNA.find((p) => p.id === SESI[token]);
}

function escapeHtml(teks) {
  return String(teks)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

app.use((req, res, next) => {
  res.set("Content-Security-Policy", "default-src 'self'; frame-ancestors 'none'");
  res.set("X-Content-Type-Options", "nosniff");
  res.set("X-Frame-Options", "DENY");
  next();
});

const GAGAL = {};
const JENDELA = 15 * 60 * 1000;

app.post("/login", (req, res) => {
  const { username, password } = req.body;
  const kini = sekarang();
  const baru = (GAGAL[username] || []).filter((t) => kini - t < JENDELA);
  GAGAL[username] = baru;
  if (baru.length >= 5) {
    res.set("Retry-After", String(Math.ceil((JENDELA - (kini - baru[0])) / 1000)));
    return res.status(429).json({ error: "Terlalu banyak percobaan, coba lagi nanti" });
  }
  const p = PENGGUNA.find((u) => u.username === username && u.password === password);
  if (!p) {
    baru.push(kini);
    return res.status(401).json({ error: "Username atau kata sandi salah" });
  }
  delete GAGAL[username];
  res.json({ token: buatToken(p.id) });
});

