  res.set("Content-Type", "text/html");
  res.send("<div class=\"kartu\"><h3>" + escapeHtml(m.nama) + "</h3><p>Rp" + m.harga + "</p></div>");
});

app.get("/pesanan/:id", (req, res) => {
  const user = penggunaDari(req);
  if (!user) return res.status(401).json({ error: "Harus login" });
  const p = PESANAN.find((x) => x.id === Number(req.params.id));
