const MENU = [
  { id: 1, nama: "Nasi Goreng", harga: 12000 },
  { id: 2, nama: "Es Teh", harga: 4000 },
  { id: 3, nama: "Teh Tarik", harga: 6000 },
  { id: 4, nama: "<script>alert('kantin')</script>", harga: 1000 },
];
const PENGGUNA = [
  { id: 1, username: "rani", password: "kantin123" },
  { id: 2, username: "bima", password: "rotiBakar9" },
];
const SESI = { "tok-rani": 1, "tok-bima": 2 };
const PESANAN = [
  { id: 1, userId: 1, menuId: 1, jumlah: 2, total: 24000 },
  { id: 2, userId: 2, menuId: 2, jumlah: 1, total: 4000 },
];
let MENIT = 0;
const sekarang = () => MENIT * 60 * 1000;
let nomorToken = 0;
function buatToken(userId) {
  const token = "tok-" + userId + "-" + ++nomorToken;
  SESI[token] = userId;
  return token;
}
// Database palsu: mendukung satu query pencarian menu.
const db = {
  log: [],
  query(sql, params = []) {
    db.log.push({ sql, params });
    if (!/^SELECT .+ FROM menu WHERE nama LIKE /i.test(sql)) throw new Error("query tidak dikenal: " + sql);
    let pola;
    if (/\?\s*$/.test(sql)) pola = String(params[0] ?? "");
    else {
      const m = sql.match(/LIKE '(.*)'\s*$/);
      pola = m ? m[1] : "";
      if (pola.includes("'")) return MENU.slice(); // input pengguna merusak query
    }
    const kata = pola.replace(/%/g, "").toLowerCase();
    return MENU.filter((m) => m.nama.toLowerCase().includes(kata));
  },
};

