const HOST_BOLEH = ["gambar.kantin.sch.id", "cdn.kantin.sch.id"];

function bolehDiambil(url) {
  if (typeof url !== "string" || !url.startsWith("https://")) return false;
  const sisa = url.slice("https://".length);
  const akhir = sisa.search(/[/?#]/);
  const host = (akhir === -1 ? sisa : sisa.slice(0, akhir)).toLowerCase();
  if (host.includes("@")) return false;
  return HOST_BOLEH.includes(host);
}

