solution.code:
const express = require("express");
const app = express();
app.use(express.json());

const GAGAL = {};
const JENDELA = 15 * 60 * 1000;

app.post("/login", (req, res) => {
  const { username, password } = req.body;
  const kini = sekarang();
  const baru = (GAGAL[username] || []).filter((t) => kini - t < JENDELA);
  GAGAL[username] = baru;
  if (baru.length >= 5) {
    LOG.push({ waktu: kini, event: "login_diblokir", username });
    const sisa = Math.ceil((JENDELA - (kini - baru[0])) / 1000);
    res.set("Retry-After", String(sisa));
    return res.status(429).json({ error: "Terlalu banyak percobaan, coba lagi nanti" });
  }
  const cocok = PENGGUNA.find((p) => p.username === username && p.password === password);
  LOG.push({ waktu: kini, event: cocok ? "login_berhasil" : "login_gagal", username });
  if (!cocok) {
    baru.push(kini);
    return res.status(401).json({ error: "Username atau kata sandi salah" });
  }
  delete GAGAL[username];
  res.json({ pesan: "Selamat datang, " + username });
});

